import{_ as a,a as d}from"./chunks/stairs-grating.CT4n5VG8.js";import{_ as e,o as i,c as o,a5 as r}from"./chunks/framework.BYXPg_yw.js";const u=JSON.parse('{"title":"계단과 단차","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/operation/stairs.md","filePath":"ko/manual/operation/stairs.md","lastUpdated":1792759058000}'),s={name:"ko/manual/operation/stairs.md"};function l(n,t,c,m,h,p){return i(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="계단과-단차" tabindex="-1">계단과 단차 <a class="header-anchor" href="#계단과-단차" aria-label="Permalink to &quot;계단과 단차&quot;">​</a></h1><p>RBQ가 넘을 수 있는 단의 높이는 어떤 <strong>보행</strong>을 쓰는지, 계단에 <strong>챌판</strong>이 있는지, 디딤판이 단 높이에 비해 얼마나 <strong>깊은지</strong>에 따라 달라집니다. 이 페이지는 보행별 한계와 그 한계가 성립하는 조건을 정리합니다. <a href="/RBQ/nightly/ko/manual/product-descriptions/general-specification.html">기본 사양</a> 페이지의 계단 수치도 이 조건에서만 성립합니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>이 페이지의 수치는 <a href="#limits">보행별 한계</a>에 적은 조건의 계단 기준입니다.</p></div></div><h2 id="terms" tabindex="-1">용어 <a class="header-anchor" href="#terms" aria-label="Permalink to &quot;용어 {#terms}&quot;">​</a></h2><figure><img style="max-width:100%;width:min(420px, 100%);height:auto;display:block;margin:1rem auto;" src="'+a+'" alt="계단 치수: A 단 높이, B 디딤판 깊이"><figcaption style="text-align:center;">[ A 단 높이 · B 디딤판 깊이 ]</figcaption></figure><table tabindex="0"><thead><tr><th></th><th>용어</th><th>뜻</th></tr></thead><tbody><tr><td>A</td><td>단 높이</td><td>한 디딤판에서 다음 디딤판까지의 수직 거리입니다. 연석이나 턱 하나도 한 단으로 봅니다.</td></tr><tr><td>B</td><td>디딤판 깊이</td><td>디딤판 하나의 앞뒤 길이로, 앞 모서리에서 뒤 끝(챌판이 있으면 챌판)까지 잽니다.</td></tr><tr><td></td><td>경사각</td><td>계단의 기울기입니다. 단 높이(A)와 디딤판 깊이(B)로 정해지며, 둘이 같으면 45° 입니다.</td></tr><tr><td></td><td>챌판</td><td>디딤판과 디딤판 사이를 막는 세로 판입니다.</td></tr><tr><td></td><td>챌판 없는 계단</td><td>챌판 없이 디딤판 사이가 뚫려 있는 계단입니다. 그레이팅 계단이 여기에 듭니다.</td></tr><tr><td></td><td>그레이팅 계단</td><td>디딤판이 아래가 비치는 금속 격자(그레이팅)로 된 계단입니다. 챌판이 없습니다.</td></tr></tbody></table><h2 id="limits" tabindex="-1">보행별 한계 <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;보행별 한계 {#limits}&quot;">​</a></h2><p>다리형 RBQ10 기준 최대 단 높이입니다.</p><table tabindex="0"><thead><tr><th>보행</th><th>챌판 있는 계단</th><th>챌판 없는 계단(그레이팅 등)</th></tr></thead><tbody><tr><td><code>STAIRS</code></td><td>최대 20 cm</td><td>최대 20 cm</td></tr><tr><td><code>RL_WALK</code>·<code>RL_WALK_VISION</code></td><td>최대 25 cm</td><td>권하지 않습니다</td></tr></tbody></table><ul><li>이 수치는 <strong>디딤판 깊이(B)가 단 높이(A)와 같은(1:1) 계단</strong>을 기준으로 정했습니다. 디딤판이 단 높이보다 깊은 계단(B &gt; A)에서도 같은 높이까지 쓸 수 있습니다. 경사각으로는 <strong>45° 이하</strong>입니다. 디딤판이 단 높이보다 얕은 계단(B &lt; A, 45° 초과)에서는 쓸 수 없습니다.</li><li>챌판 없는 계단에서는 <code>STAIRS</code> 를 고르세요. <code>RL_WALK</code>·<code>RL_WALK_VISION</code> 은 권하지 않습니다.</li><li>25 cm 는 <code>Vision Walk</code> 를 켠 <code>RL_WALK_VISION</code> 기준입니다.</li></ul><h2 id="grating" tabindex="-1">그레이팅 계단 <a class="header-anchor" href="#grating" aria-label="Permalink to &quot;그레이팅 계단 {#grating}&quot;">​</a></h2><p><code>STAIRS</code> 보행은 몸체 아래 깊이 카메라로 그레이팅 디딤판을 계단으로 인식합니다. 그레이팅 계단에는 챌판이 없으므로 <code>STAIRS</code> 를 고르세요. <code>RL_WALK</code>·<code>RL_WALK_VISION</code> 은 권하지 않습니다.</p><figure><img style="max-width:100%;width:min(420px, 100%);height:auto;display:block;margin:1rem auto;" src="'+d+'" alt="그레이팅 디딤판 윗면: 격자 구멍 가로 95 mm, 세로 25 mm, 화살표는 진행 방향"><figcaption style="text-align:center;">[ 최대 격자 구멍 크기: 가로 95 mm × 세로 25 mm · 화살표는 진행 방향 ]</figcaption></figure><ul><li>격자 구멍이 가로 95 mm × 세로 25 mm 보다 넓은 그레이팅은 권하지 않습니다.</li><li>단 높이와 경사각의 한계는 <a href="#limits">보행별 한계</a>와 같습니다.</li></ul>',14)])])}const b=e(s,[["render",l]]);export{u as __pageData,b as default};
